// Review-only host for the real published game iframe. Engine-produced example
// saves remain in this tab's memory, separate from account and browser saves.
const fixtures=await(await fetch('./fixtures.json')).json();
const names={execute:['被斩 · A','Executed · A'],jail:['下狱 · B','Imprisoned · B'],exile:['逐出 · B','Sent away · B'],wounded:['负伤 · A','Wounded · A']};
const params=new URLSearchParams(location.search);let lang=params.get('lang')==='en'?'en':'zh',kind=Object.hasOwn(names,params.get('fate'))?params.get('fate'):'jail',stage='after',ink=false,snapshot={};
const frame=document.querySelector('#game'),q=s=>document.querySelector(s),text=(zh,en)=>lang==='zh'?zh:en;
// Open the sole isolated example using the game's own Continue / Look back control.
frame.addEventListener('load',()=>{const doc=frame.contentDocument;if(!doc)return;const open=()=>{const b=doc.querySelector('.saverow .btn');if(b){observer.disconnect();b.click();return true;}return false;};const observer=new MutationObserver(open);if(!open())observer.observe(doc.documentElement,{childList:true,subtree:true});});
function load(keep=false){const g=structuredClone(fixtures[kind][stage]);if(!keep)snapshot={'campaign.settings':{lang},'campaign.cur':g.run,'campaign.runN':1,['campaign.run.'+g.run]:g,'campaign.runs':[{id:g.run,vol:g.vol,n:1,created:g.created,updated:g.created,status:g.phase==='end'?'end':'play',dead:!!g.v['flag.fate_dead'],early:!!g.v.ended_early,ch:g.ch,node:g.cur}]};
 snapshot['campaign.settings']={...(snapshot['campaign.settings']||{}),lang};frame.src='/assets/sanguo-campaign'+(ink?'':'-illus')+'.html';draw();}
function draw(){document.documentElement.lang=lang;document.title=text('命运图试玩','Fate illustration playtest')+' · StoryDate';q('#heading').textContent=text('命运图 · 实际图文位置','Fate illustrations · In the real game');q('#gallery').textContent=text('对比全部 A / B 候选','Compare all A / B candidates');q('#language').textContent=lang==='zh'?'English':'中文';q('#intro').textContent=text('这是隔离的试玩存档，用现有规则走出的四种下场。默认看结果；点“回到选择前”可以亲自选。这里的操作只留在本页，不写入账号或覆盖你的游戏进度。','These isolated example saves reached four outcomes through existing rules. View a result or return to its preceding choice. Actions here stay in this tab and never overwrite your account or game saves.');q('#before').textContent=text('回到选择前','Before the choice');q('#after').textContent=text('查看结果配图','View the illustrated result');q('#edition').textContent=ink?text('切回插画版','Use illustrations'):text('对比水墨版','Compare ink edition');q('#normal').textContent=text('正常开始游戏 ↗','Open the full game ↗');q('#normal').href='/play/three-kingdoms?lang='+lang;q('#status').textContent=names[kind][lang==='zh'?0:1]+' · '+text(stage==='before'?'选择前':'结果存档',stage==='before'?'Before the choice':'Outcome save');for(const b of q('#fates').children)b.setAttribute('aria-pressed',String(b.dataset.fate===kind));}
for(const[k,v]of Object.entries(names)){const b=document.createElement('button');b.dataset.fate=k;b.textContent=v[lang==='zh'?0:1];b.onclick=()=>{kind=k;stage='after';load();};q('#fates').append(b);}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;const d=e.data;if(d?.type==='sg2-ready')frame.contentWindow.postMessage({type:'sg2-init',snapshot},location.origin);if(d?.type==='sg2-save'&&typeof d.key==='string'&&d.key.startsWith('campaign.')){if(d.value===null)delete snapshot[d.key];else snapshot[d.key]=d.value;if(d.key==='campaign.run.fate-review-'+kind&&d.value?.log?.some(x=>x.k==='choice'&&x.n===fixtures[kind].node&&x.c===fixtures[kind].choice)){stage='after';draw();}}});
q('#language').onclick=()=>{lang=lang==='zh'?'en':'zh';for(const b of q('#fates').children)b.textContent=names[b.dataset.fate][lang==='zh'?0:1];load(true);};q('#before').onclick=()=>{stage='before';load();};q('#after').onclick=()=>{stage='after';load();};q('#edition').onclick=()=>{ink=!ink;load(true);};load();
